public class NonGenericDemo
{
    public static void Main()
    {
        ArrayList items = new ArrayList();
        items.Add(1);          // int boxed to object
        items.Add("Hello");   // string (already a reference type)
        items.Add(2.5);        // double boxed to object

        // Must cast back — and risk InvalidCastException
        foreach (object item in items)
        {
            // int i = item; // Compile error — cannot convert object to int
            int i = (int)item; // Throws at runtime for "Hello" and 2.5
            Console.WriteLine(i);
        }
