using System;

public class GenericMethodDemo
{
    // T is the type parameter — it stands in for any type
    static T GetDefault<T>()
    {
        // default(T) returns the zero-initialized value for any type:
        // null for reference types, 0 for numeric types, false for bool
        return default(T);
    }

    public static void Main()
    {
        // Explicit type argument
        int defaultInt = GetDefault<int>();    // 0
        string? defaultStr = GetDefault<string>(); // null
        bool defaultBool = GetDefault<bool>(); // false

        // Compiler can infer the type from the context
        double inferred = GetDefault<double>(); // 0.0

        // Generic method with multiple type parameters
        static void Swap<T>(ref T a, ref T b)
        {
            T temp = a;
            a = b;
            b = temp;
        }

        int x = 10, y = 20;
        Swap(ref x, ref y);
        Console.WriteLine($"x={x}, y={y}"); // x=20, y=10
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

// T is the type of entity this repository manages
public class Repository<T> where T : class
{
    private List<T> _items = new List<T>();

    public void Add(T item)
    {
        if (item == null) throw new ArgumentNullException(nameof(item));
        _items.Add(item);
    }

    public T? GetById(int id)
    {
        // Simple index-based retrieval for demo purposes
        return id >= 0 && id < _items.Count ? _items[id] : null;
    }

    public List<T> GetAll()
    {
        // Return a copy to prevent external mutation
        return new List<T>(_items);
    }

    public bool Remove(T item)
    {
        return _items.Remove(item);
    }

    public int Count => _items.Count;
}

// Domain models
public class User
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
}

public class Product
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public decimal Price { get; set; }
}

public class RepositoryDemo
{
    public static void Main()
    {
        // Same Repository class, two different types
        Repository<User> userRepo = new Repository<User>();
        userRepo.Add(new User { Id = 0, Name = "Alice" });
        userRepo.Add(new User { Id = 1, Name = "Bob" });

        Repository<Product> productRepo = new Repository<Product>();
        productRepo.Add(new Product { Id = 0, Name = "Laptop", Price = 999 });

        User? user = userRepo.GetById(0);
        Console.WriteLine(user?.Name); // Alice
    }
}

using System;
using System.Collections.Generic;

public interface IRepository<T>
{
    void Add(T item);
    T? GetById(int id);
    List<T> GetAll();
    bool Remove(T item);
}

// In-memory implementation
public class InMemoryRepository<T> : IRepository<T> where T : class
{
    private List<T> _items = new List<T>();
    public void Add(T item) => _items.Add(item ?? throw new ArgumentNullException());
    public T? GetById(int id) => id >= 0 && id < _items.Count ? _items[id] : null;
    public List<T> GetAll() => new List<T>(_items);
    public bool Remove(T item) => _items.Remove(item);
}

// Usage — same interface, different types
IRepository<User> users = new InMemoryRepository<User>();
IRepository<Product> products = new InMemoryRepository<Product>();

using System;

// Constraints: class (reference type), new() (parameterless ctor),
// IComparable<T> (can be sorted/comparison operated)
public class SortedCache<T> where T : class, IComparable<T>, new()
{
    private List<T> _items = new List<T>();

    public void Add(T item)
    {
        if (item == null) throw new ArgumentNullException();
        _items.Add(item);
        _items.Sort(); // IComparable<T>.CompareTo is now available
    }

    public T CreateDefault()
    {
        return new T(); // new() constraint makes this legal
    }
}

public class Employee : IComparable<Employee>
{
    public string Name { get; set; } = string.Empty;
    public int Salary { get; set; }

    public int CompareTo(Employee? other)
    {
        if (other == null) return 1;
        return Salary.CompareTo(other.Salary);
    }
}

public class ConstraintDemo
{
    public static void Main()
    {
        var cache = new SortedCache<Employee>();
        cache.Add(new Employee { Name = "Alice", Salary = 90000 });
        cache.Add(new Employee { Name = "Bob", Salary = 75000 });

        Employee defaultEmp = cache.CreateDefault();
        Console.WriteLine($"Default: {defaultEmp.Name}"); // empty string
    }
}

using System;
using System.Collections.Generic;

public class Animal { public string Name { get; set; } = string.Empty; }
public class Dog : Animal { public void Bark() => Console.WriteLine("Woof!"); }
public class Cat : Animal { public void Meow() => Console.WriteLine("Meow!"); }

public class VarianceDemo
{
    public static void Main()
    {
        List<Dog> dogs = new List<Dog>
        {
            new Dog { Name = "Rex" },
            new Dog { Name = "Buddy" }
        };

        // IEnumerable<out T> is covariant — List<Dog> can be treated as IEnumerable<Animal>
        IEnumerable<Animal> animals = dogs;
        foreach (Animal a in animals)
        {
            Console.WriteLine(a.Name); // Rex, Buddy
        }
    }
}
